{
  "missing_information": [
    {
      "category": "actor",
      "gap": "It is unclear who initiates the measurement workflow and whether different tools require different operators or certifications.",
      "why_it_matters": "Automation feasibility depends on whether a human must be present at each tool or if robotic/automated loading is possible."
    },
    {
      "category": "decision",
      "gap": "The criteria for selecting which tool to use for a given wafer are not defined.",
      "why_it_matters": "Tool selection logic is a key branching point; if rule-based, it can be automated; if judgment-based, it requires human involvement."
    },
    {
      "category": "input",
      "gap": "The specific preparation steps required before measurement for each tool type are not described.",
      "why_it_matters": "Preparation steps may involve manual handling, calibration, or chemical treatment that significantly affects automation complexity and cycle time."
    },
    {
      "category": "output",
      "gap": "The format, destination, and validation requirements for the recorded measurement result are unspecified.",
      "why_it_matters": "If results must be entered manually into a system, this is a prime automation target; structured digital output enables direct integration."
    },
    {
      "category": "exception",
      "gap": "There is no information about what happens when a measurement is out of specification or a tool malfunctions.",
      "why_it_matters": "Exception paths often require human judgment or escalation and must be modeled to assess end-to-end automation coverage."
    },
    {
      "category": "frequency",
      "gap": "The volume of wafers measured per shift or day and the frequency of tool switches are unknown.",
      "why_it_matters": "High-frequency, repetitive workflows justify automation investment; low-frequency or highly variable ones may not."
    },
    {
      "category": "integration_constraint",
      "gap": "It is unclear whether the measurement tools expose data interfaces (e.g., APIs, file exports) or require manual data retrieval.",
      "why_it_matters": "Tool integration capability is a hard constraint on whether measurement data can be automatically captured without human transcription."
    },
    {
      "category": "manual_effort",
      "gap": "The step where the engineer 'records the result' is vague — it is unknown whether this is a manual log entry, a system form, or a verbal report.",
      "why_it_matters": "The recording step is the most visible manual effort and a primary candidate for automation if the data is already digitally available."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What criteria or rules determine which measurement tool is selected for a given wafer — for example, wafer type, lot specification, or tool availability?",
      "targets": ["decision"]
    },
    {
      "id": "Q2",
      "question": "Can you describe the preparation steps that must be completed before measurement begins, and do these steps differ significantly between tools?",
      "targets": ["input"]
    },
    {
      "id": "Q3",
      "question": "When the engineer records the measurement result, what exactly does that involve — is it a manual entry into a form or system, a physical log, or does the tool output data automatically?",
      "targets": ["output", "manual_effort"]
    },
    {
      "id": "Q4",
      "question": "Do the measurement tools have any data export capability, such as file outputs, network interfaces, or APIs that could be used to retrieve results programmatically?",
      "targets": ["integration_constraint"]
    },
    {
      "id": "Q5",
      "question": "What happens when a measurement result falls outside the acceptable specification range — is there a defined escalation or rework path?",
      "targets": ["exception"]
    },
    {
      "id": "Q6",
      "question": "Approximately how many wafers go through this measurement workflow per shift or per day, and how often does the active tool change during that period?",
      "targets": ["frequency"]
    }
  ]
}
